s0 AS (SELECT LEFT(public_key,8) k, di_dictionary_num_matched_at_session_created d, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, IFF(latest_risk_band='High',1,0) hi, IFF(sessions_verified>0,1,0) ver, IFF(was_challenged>0,1,0) chl, IFF(was_challenged>0 AND COALESCE(sessions_solved,0)=0,1,0) chns, di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, COALESCE(di_short_term_threshold_ratio_at_session_created,0) str, IFF(di_short_term_threshold_breached_at_session_created,1,0) stb, IFF(di_long_term_threshold_breached_at_session_created,1,0) ltb FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key IN ('EE844FC3-499D-4A4D-A643-D7400F0FD4DE','E3EFEFBF-8DE4-42ED-9E7F-92F35B1FD3CF','7CC24C4A-611B-41C7-9808-B95722C7861C') AND session_last_timestamp>='2026-11-18 10:00' AND session_last_timestamp<'2026-11-18 20:00' AND session_ts>='2026-11-18 10:00' AND session_ts<'2026-11-18 14:00' AND di_dictionary_num_matched_at_session_created IS NOT NULL),
s1 AS (SELECT s0.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp FROM s0),
f AS (SELECT s1.*, g.tst, g.tlt, IFF(x IS NULL AND (stc>g.tst OR ltc>g.tlt),1,0) na, IFF(x IS NULL AND stc>g.tst,1,0) nst FROM s1 LEFT JOIN g ON g.k=s1.k AND g.d=s1.d AND g.grp=s1.grp)
SELECT COALESCE(k,'ALL')||'|'||COALESCE(d::STRING,'ALL')||'|'||COALESCE(IFF(x IS NULL,grp,'SKIP_'||x),'ALL')||'|n='||COUNT(*)||'|hi='||ROUND(100*AVG(hi),1)||'|ver='||ROUND(100*AVG(ver),1)||'|thr='||COALESCE(MAX(tst)::STRING,'-')||'/'||COALESCE(MAX(tlt)::STRING,'-')||'|stc_p50/max='||MEDIAN(stc)||'/'||MAX(stc)
 ||'|T='||SUM(stb)||'/'||COALESCE(ROUND(100*SUM(stb*hi)/NULLIF(SUM(stb),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(stb*ver)/NULLIF(SUM(stb),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(stb*chl)/NULLIF(SUM(stb),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(stb*chns)/NULLIF(SUM(stb),0),1)::STRING,'-')||'|T2='||SUM(IFF(str>=2,1,0))||'|T4='||SUM(IFF(str>=4,1,0))||'|TL='||SUM(ltb)
 ||'|NA='||SUM(na)||'/'||COALESCE(ROUND(100*SUM(na*hi)/NULLIF(SUM(na),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(na*ver)/NULLIF(SUM(na),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(na*chl)/NULLIF(SUM(na),0),1)::STRING,'-')||'/'||COALESCE(ROUND(100*SUM(na*chns)/NULLIF(SUM(na),0),1)::STRING,'-')||'|NST='||SUM(nst) r
FROM f GROUP BY GROUPING SETS ((k,d,x,grp),(k),()) HAVING COUNT(*)>=100 OR d IS NULL ORDER BY 1
;
